using System.Reflection;
using System.Text.Json;
using Comfort.Common;
using EFT;
using EFT.Ballistics;
using EFT.HealthSystem;
using EFT.InventoryLogic;
using EscapeFromBorderlands.Client;
using UnityEngine;

var catalog=LegendaryCatalog.Load();var results=new List<object>();int passed=0,failed=0;
void Assert(bool value,string message){if(!value)throw new Exception(message);}
void Close(float actual,float expected,string message){Assert(Math.Abs(actual-expected)<.0005f,$"{message}: {actual} != {expected}");}
void Test(string name,Action test){Time.time=0;MasterKeyRuntime.Reset();GameWorld.InteractionTarget=null;GameWorld.InteractionDistance=0;GameWorld.InteractionQueries=0;MeleeRuntime.Reset();RarityResolver.ResetSession();MeleeAnimation.Reset();Singleton<GameWorld>.Instance=new();try{test();passed++;results.Add(new{name,status="PASS"});Console.WriteLine("PASS "+name);}catch(Exception e){failed++;results.Add(new{name,status="FAIL",error=e.GetBaseException().Message});Console.WriteLine("FAIL "+name+": "+e.GetBaseException().Message);}}
object? Patch(Type type,string name,object?[] args)=>type.GetMethod(name,BindingFlags.Static|BindingFlags.NonPublic)!.Invoke(null,args);
(Player player,Player.KnifeController controller,Item item,RarityResolver.ShotRoll roll) Setup(string key,bool neutral=true)
{
    var definition=catalog.Variants.Single(v=>v.SpecialId=="melee_"+key);var item=new Item{Id=key,StringTemplateId=definition.TemplateId};var player=new Player();var controller=new Player.KnifeController(player,item);player.HandsController=controller;Singleton<GameWorld>.Instance.AllAlivePlayersList.Add(player);var roll=RarityResolver.Resolve(item)!;
    if(neutral){roll.MeleeSlashMultiplier=roll.MeleeStabMultiplier=roll.MeleeAttackSpeedMultiplier=roll.MeleeReachMultiplier=roll.MeleeSwapMultiplier=roll.PenetrationMultiplier=1;}
    MeleeRuntime.Maintain(Singleton<GameWorld>.Instance);return(player,controller,item,roll);
}
Player Target(){var target=new Player();Singleton<GameWorld>.Instance.AllAlivePlayersList.Add(target);return target;}
void Attack(Player.KnifeController controller,bool stab=false)
{
    Patch(typeof(LegendaryMeleeAttackStartPatch),"Prefix",[new Player.KnifeController.Kick(controller),stab?Player.EKickType.Stab:Player.EKickType.Slash]);controller.LastKickType=stab?Player.EKickType.Stab:Player.EKickType.Slash;
}
DamageInfo Damage(Player attacker,Item item,Player target,EBodyPart part=EBodyPart.Chest)=>new(){DamageType=EDamageType.Melee,Damage=100,PenetrationPower=20,Weapon=item,Player=new Owner(attacker),HittedBallisticCollider=new BodyPartCollider{PlayerProfileID=target.ProfileId,BodyPartType=part}};
DamageInfo Scale(DamageInfo info){object?[] a=[Singleton<GameWorld>.Instance,info];Patch(typeof(LegendaryMeleeDamagePatch),"Prefix",a);return(DamageInfo)a[1]!;}
float Hit(Player target,EBodyPart part,DamageInfo info)
{
    object?[] a=[target.ActiveHealthController,info.Damage,info,null];Patch(typeof(LegendaryMeleeHealthPatch),"Prefix",a);info=(DamageInfo)a[2]!;var damage=(float)a[1]!;var result=target.ActiveHealthController.ApplyDamage(part,damage,info);Patch(typeof(LegendaryMeleeHealthPatch),"Postfix",[target.ActiveHealthController,part,info,result,a[3]]);return result;
}
float Total(Player p)=>p.HealthController.Parts.Values.Sum(h=>h.Current);

Test("All 48 approved melee variants are active; discarded entries stay absent",()=>{var definitions=catalog.Variants.Where(v=>v.MeleeEffect!=null).ToArray();Assert(definitions.Length==48,"catalog count");Assert(definitions.All(v=>v.AffixCount==4&&v.BackgroundColor=="orange"&&v.Tier=="Legendary"),"rarity/modifiers");Assert(!definitions.Any(v=>v.SourceTemplateId is "63495c500c297e20065a08b1" or "670ad7f1ad195290cd00da7a" or "6087e570b998180e9f76dc24" or "679ba90d269ddfea47012159"),"discarded variant");Assert(definitions.Select(v=>v.TemplateId).Distinct().Count()==48,"ID collision");});
Test("All four retired Labrys/hammer variants resolve without Legendary bonuses or active melee state",()=>{
    foreach(var id in new[]{"ee062a729e7bf848fc0a317f","df1923a15cd23b2c43aae687","fa30522c1ddb11ac589374ee","8ed3212f682ffaca559999ff","6087e570b998180e9f76dc24","679ba90d269ddfea47012159"})
    {
        var item=new Item{Id="retired-"+id,StringTemplateId=id};var player=new Player();var controller=new Player.KnifeController(player,item);player.HandsController=controller;Singleton<GameWorld>.Instance.AllAlivePlayersList.Add(player);
        Assert(RarityResolver.Resolve(item)==null&&MeleeRuntime.Held(player)==null,"retired weapon kept EFB bonuses");
        Attack(controller);Close(Scale(Damage(player,item,Target())).Damage,100,"retired damage altered");
        var attacker=Target();var info=Damage(attacker,new(),player);info.DamageType=EDamageType.Bullet;object?[] args=[player.ActiveHealthController,100f,info,null];Patch(typeof(LegendaryMeleeHealthPatch),"Prefix",args);Close((float)args[1]!,100,"retired protection remains");
    }
});
Test("Every melee instance gets four distinct stable melee modifiers and different items can differ",()=>{foreach(var d in catalog.Variants.Where(v=>v.MeleeEffect!=null)){var signatures=new HashSet<string>();for(var i=0;i<30;i++){var item=new Item{Id="instance"+i,StringTemplateId=d.TemplateId};var r=RarityResolver.Resolve(item)!;Assert(r.AffixDescriptions.Count==5,"modifier count");Assert(!r.AffixDescriptions.Skip(1).Any(s=>s.Contains("projectile")||s.Contains("recoil")||s.Contains("fire rate")),"firearm affix on melee");var text=string.Join("|",r.AffixDescriptions);signatures.Add(text);RarityResolver.ResetSession();Assert(string.Join("|",RarityResolver.Resolve(item)!.AffixDescriptions)==text,"reroll changed");}Assert(signatures.Count>1,"all copies identical");}});
Test("Point Taken affects stabs only and composes once with random damage/penetration",()=>{var t=Setup("point_taken");var victim=Target();t.roll.MeleeStabMultiplier=1.2f;t.roll.MeleeSlashMultiplier=1.15f;t.roll.PenetrationMultiplier=1.1f;Attack(t.controller,true);var info=Scale(Damage(t.player,t.item,victim));Close(info.Damage,360,"stab");Close(info.PenetrationPower,22,"penetration");Attack(t.controller);Close(Scale(Damage(t.player,t.item,victim)).Damage,115,"slash");});
Test("Standard Issue accepts either primary and EFB AK-74 clones, excludes backpack and AK-105",()=>{var t=Setup("standard_issue");var e=t.player.InventoryController.Inventory.Equipment;Assert(MeleeRuntime.Effect(t.player)==null,"ungated");foreach(var slot in new[]{EquipmentSlot.FirstPrimaryWeapon,EquipmentSlot.SecondPrimaryWeapon}){e.GetSlot(slot).ContainedItem=new(){StringTemplateId="5644bd2b4bdc2d3b4c8b4572"};Assert(MeleeRuntime.Effect(t.player)!=null,"primary excluded");Close(MeleeRuntime.SwapSpeed(t.controller),2,"swap");e.GetSlot(slot).ContainedItem=null;}var ak=catalog.Variants.First(v=>v.SourceTemplateId=="5ac4cd105acfc40016339859");e.GetSlot(EquipmentSlot.SecondPrimaryWeapon).ContainedItem=new(){StringTemplateId=ak.TemplateId};Assert(MeleeRuntime.Effect(t.player)!=null,"clone excluded");e.GetSlot(EquipmentSlot.SecondPrimaryWeapon).ContainedItem=null;e.GetSlot(EquipmentSlot.Backpack).ContainedItem=new(){StringTemplateId=ak.TemplateId};Assert(MeleeRuntime.Effect(t.player)==null,"backpack qualified");e.GetSlot(EquipmentSlot.FirstPrimaryWeapon).ContainedItem=new(){StringTemplateId="5ac66d9b5acfc4001633997a"};Assert(MeleeRuntime.Effect(t.player)==null,"AK105 qualified");});
Test("Spy Main rear hits receive 7.66x damage; front/side hits receive ordinary damage",()=>{var t=Setup("spy_main");var victim=Target();Attack(t.controller);foreach(var (position,mult) in new[]{(new Vector3(0,0,-1),7.66f),(new Vector3(0,0,1),1f),(new Vector3(1,0,0),1f)}){t.player.Position=position;Close(Scale(Damage(t.player,t.item,victim)).Damage,100*mult,"direction");}});
Test("Shark Bite requires an existing bleed before its hit",()=>{var t=Setup("shark_bite");var victim=Target();Attack(t.controller);Close(Scale(Damage(t.player,t.item,victim)).Damage,100,"not bleeding");victim.ActiveHealthController.Effects.Add(new ActiveHealthController.Bleeding(){Existing=true});Close(Scale(Damage(t.player,t.item,victim)).Damage,350,"bleeding");victim.ActiveHealthController.Effects[0].Existing=false;Close(Scale(Damage(t.player,t.item,victim)).Damage,100,"expired bleed");});
Test("Roberto applies heavy bleed only on flesh-damaging stabs",()=>{var t=Setup("roberto");var victim=Target();Attack(t.controller);Hit(victim,EBodyPart.Chest,Damage(t.player,t.item,victim));Assert(victim.ActiveHealthController.Effects.Count==0,"slash bleed");Attack(t.controller,true);var blocked=Damage(t.player,t.item,victim);blocked.BlockedBy=1;blocked.Damage=2;Hit(victim,EBodyPart.Chest,blocked);Assert(victim.ActiveHealthController.Effects.Count==0,"armor bleed");Attack(t.controller,true);Hit(victim,EBodyPart.Stomach,Damage(t.player,t.item,victim));Assert(victim.ActiveHealthController.Effects.Count==1,"flesh stab did not bleed");});
Test("Red Tide increments once per successful attack, caps at +300%, and resets on holster",()=>{var t=Setup("red_tide");var victim=Target();for(var i=0;i<15;i++){Attack(t.controller);Close(Scale(Damage(t.player,t.item,victim)).Damage,100*(1+Math.Min(3,i*.25f)),"buildup "+i);MeleeRuntime.OnDamage(victim,EBodyPart.Chest,Damage(t.player,t.item,victim),1,true);MeleeRuntime.OnDamage(victim,EBodyPart.Chest,Damage(t.player,t.item,victim),1,true);}Close(MeleeRuntime.Held(t.player)!.Buildup,3,"cap");t.player.HandsController=null;MeleeRuntime.Maintain(Singleton<GameWorld>.Instance);t.player.HandsController=t.controller;Attack(t.controller);Close(Scale(Damage(t.player,t.item,victim)).Damage,100,"holster reset");});
Test("Third Time's the Chop counts missed attacks, empowers every third, and resets on switching",()=>{var t=Setup("third_chop");var victim=Target();for(var i=1;i<=6;i++){Attack(t.controller);Close(Scale(Damage(t.player,t.item,victim)).Damage,i%3==0?400:100,"attack "+i);}t.player.HandsController=null;MeleeRuntime.Held(t.player);t.player.HandsController=t.controller;Attack(t.controller);Close(Scale(Damage(t.player,t.item,victim)).Damage,100,"reset");});
