Test("Blood Bank heals ten total HP only once per flesh attack and never restores blacked parts",()=>{var t=Setup("blood_bank");var victim=Target();t.player.ActiveHealthController.Parts[EBodyPart.LeftArm].Current=0;t.player.ActiveHealthController.Parts[EBodyPart.Chest].Current=50;t.player.ActiveHealthController.Parts[EBodyPart.Stomach].Current=75;var before=Total(t.player);Attack(t.controller);MeleeRuntime.OnDamage(victim,EBodyPart.Chest,Damage(t.player,t.item,victim),2,true);MeleeRuntime.OnDamage(victim,EBodyPart.Chest,Damage(t.player,t.item,victim),2,true);Close(Total(t.player)-before,10,"total healing");Close(t.player.ActiveHealthController.Parts[EBodyPart.LeftArm].Current,0,"blacked arm");Attack(t.controller);var blocked=Damage(t.player,t.item,victim);blocked.BlockedBy=1;before=Total(t.player);MeleeRuntime.OnDamage(victim,EBodyPart.Chest,blocked,2,true);Close(Total(t.player),before,"armor leech");});
Test("Trench Foot boosts leg damage and fractures only flesh-damaging leg hits",()=>{var t=Setup("trench_foot");var victim=Target();Attack(t.controller);Close(Scale(Damage(t.player,t.item,victim,EBodyPart.LeftLeg)).Damage,250,"leg");Close(Scale(Damage(t.player,t.item,victim)).Damage,100,"torso");var blocked=Damage(t.player,t.item,victim,EBodyPart.LeftLeg);blocked.BlockedBy=1;Hit(victim,EBodyPart.LeftLeg,blocked);Assert(victim.ActiveHealthController.Fractures.Count==0,"armor fracture");Attack(t.controller);Hit(victim,EBodyPart.RightLeg,Damage(t.player,t.item,victim,EBodyPart.RightLeg));Assert(victim.ActiveHealthController.Fractures.Single()==EBodyPart.RightLeg,"leg fracture");});
