Test("Summit and Trailblazer affect only jump/sprint Leg Stamina; restoration and other consumption remain native",()=>{foreach(var (key,sprintFactor) in new[]{("summit_fever",.75f),("trailblazer",.6f)}){var t=Setup(key);var stamina=t.player.Physical.Stamina;stamina.Current=100;var sprint=new Physical.Consumption(Physical.EConsumptionType.Sprint);var walk=new Physical.Consumption(Physical.EConsumptionType.Walk){Delta=new(()=>5)};stamina.Consumptions.AddRange([sprint,walk]);var original=sprint.Delta;object?[] a=[stamina,null];Patch(typeof(LegendaryMeleeSprintCostPatch),"Prefix",a);stamina.Process(1);Patch(typeof(LegendaryMeleeSprintCostPatch),"Finalizer",[a[1],null]);Close(stamina.Current,100-(10*sprintFactor+5),"sprint cost");Assert(ReferenceEquals(sprint.Delta,original),"shared delta retained");}var s=Setup("summit_fever");var leg=s.player.Physical.Stamina;leg.Current=100;leg.Multiplier=.8f;var jump=new Physical.Consumption(Physical.EConsumptionType.Jump);object?[] b=[leg,jump,null];Patch(typeof(LegendaryStaminaCostPatch),"Prefix",b);leg.Consume(jump);Patch(typeof(LegendaryStaminaCostPatch),"Finalizer",[leg,b[2],null]);Close(leg.Current,96.8f,"jump");Close(leg.Multiplier,.8f,"multiplier restoration");b=[s.player.Physical.HandsStamina,jump,null];Patch(typeof(LegendaryStaminaCostPatch),"Prefix",b);Close(s.player.Physical.HandsStamina.Multiplier,1,"hands cost");Patch(typeof(LegendaryStaminaCostPatch),"Finalizer",[s.player.Physical.HandsStamina,b[2],null]);});
