Test("Swing speed, reach, and inspect attributes include signature and random modifiers",()=>{var t=Setup("swiss_army_axe");t.controller.CurrentKnifeOperation=new Player.KnifeController.Kick(t.controller);t.roll.MeleeAttackSpeedMultiplier=1.2f;object?[] a=[t.controller,1f];Patch(typeof(LegendaryMeleeSpeedPatch),"Prefix",a);Close((float)a[1]!,2.1f,"swing");var sword=Setup("long_arm");sword.roll.MeleeReachMultiplier=1.1f;var collider=new KnifeCollider{MaxDistance=.8f};Patch(typeof(LegendaryMeleeReachPatch),"Prefix",[collider,sword.controller]);Close(collider.MaxDistance,.8f*1.35f*1.1f,"reach");var component=new KnifeComponent(sword.item,new IKnifeComponentTemplate());Patch(typeof(LegendaryMeleeAttributePatch),"Postfix",[component]);Close(sword.item.Attributes.Single(a=>a.Id==EItemAttributeId.KnifeHitSlashDam).Base(),30,"slash display");Close(sword.item.Attributes.Single(a=>a.Id==EItemAttributeId.KnifeHitStabDam).Base(),30,"stab display");});
