    other.player.InventoryController.Inventory.Equipment.GetSlot(EquipmentSlot.Scabbard).ContainedItem=new Item{Id="ordinary-red-rebel",StringTemplateId="5c0126f40db834002a125382"};object?[] native=[new HasItemRequirement{Id="5c0126f40db834002a125382"},other.player,true];Patch(typeof(LegendaryRedRebelExtractionPatch),"Postfix",native);Assert((bool)native[2]!,"native successful check was changed");
