void Tick(float seconds, Player? moving=null, bool sprint=false)
{
    for(var elapsed=0f;elapsed<seconds-.0001f;elapsed+=.1f)
    {
        Time.time+=.1f;
        if(moving!=null){moving.InputDirection=new(0,1);moving.Position.z+=.1f;moving.MovementContext.IsSprintEnabled=sprint;}
        MeleeRuntime.Maintain(Singleton<GameWorld>.Instance);AdvancedMeleeRuntime.Maintain(Singleton<GameWorld>.Instance);
    }
}
