Test("Session cleanup removes owned painkillers without touching medicine or unchanged carried weight",()=>{var t=Setup("hoodoo");var h=t.player.ActiveHealthController;var medicine=new ActiveHealthController.Effect();h.Effects.Add(medicine);Tick(.1f);var own=h.Effects.Single(e=>e.GetType().Name=="PainKiller");MeleeRuntime.Reset();Assert(!own.Existing&&medicine.Existing,"held painkiller survived reset or medicine removed");var r=Setup("rifleman_s_ration");AdvancedMeleeRuntime.Kill(MeleeRuntime.Held(r.player)!);var ration=r.player.ActiveHealthController.Effects.Single();MeleeRuntime.Reset();Assert(!ration.Existing,"kill painkiller survived session reset");var w=Setup("damascus_delivery");AdvancedMeleeRuntime.Maintain(Singleton<GameWorld>.Instance);var updates=w.player.Physical.WeightUpdates;MeleeRuntime.Reset();Assert(w.player.Physical.WeightUpdates==updates&&!AdvancedMeleeRuntime.Resetting,"reset changed native weight without a weight modifier");});

Test("Emergency Access opens one locked door without breach eligibility and leaves its four-modifier item identity intact",()=>{var t=Setup("emergency_access");var d=new EFT.Interactive.Door{DoorState=EFT.Interactive.EDoorState.Locked,CanBeBreached=false,CanInteractWithBreach=false};Patch(typeof(LegendaryMeleeDoorUnlockPatch),"Prefix",[t.controller,new Player.KnifeRaycastHit{collider=new Component{Parent=d}}]);Assert(d.DoorState==EFT.Interactive.EDoorState.Open&&d.Breaches==0&&!d.IsBroken&&d.User==t.player,"native unlock/open did not run");var second=new EFT.Interactive.Door{DoorState=EFT.Interactive.EDoorState.Locked};Assert(!MasterKeyRuntime.TryUnlock(t.player,second)&&second.DoorState==EFT.Interactive.EDoorState.Locked,"second use allowed");Assert(t.roll.Definition.TemplateId=="65ec96e867cb2c48bcbd9fab"&&t.roll.Definition.AffixCount==4,"item identity or affixes changed");});
Test("Walls, unlocked doors, non-interactive barriers and refused unlocks do not spend the master-key charge",()=>{var t=Setup("emergency_access");Assert(!MasterKeyRuntime.TryUnlock(t.player,null),"wall counted");foreach(var d in new[]{new EFT.Interactive.Door{DoorState=EFT.Interactive.EDoorState.Shut},new(){DoorState=EFT.Interactive.EDoorState.Open},new(){DoorState=EFT.Interactive.EDoorState.Locked,Operatable=false},new(){DoorState=EFT.Interactive.EDoorState.Locked,NoInteractionsAllowed=true},new(){DoorState=EFT.Interactive.EDoorState.Locked,Refuse=true}})Assert(!MasterKeyRuntime.TryUnlock(t.player,d),"ineligible door unlocked");Assert(MasterKeyRuntime.TryUnlock(t.player,new(){DoorState=EFT.Interactive.EDoorState.Locked}),"failed attempt spent charge");});
Test("Emergency Access shares its raid charge across copies, holsters and recreated actors with the same profile",()=>{var t=Setup("emergency_access");Assert(MasterKeyRuntime.TryUnlock(t.player,new(){DoorState=EFT.Interactive.EDoorState.Locked}),"initial use");t.player.HandsController=null;MeleeRuntime.Maintain(Singleton<GameWorld>.Instance);var copy=new Item{Id="other-copy",StringTemplateId=t.item.StringTemplateId};t.player.HandsController=new Player.KnifeController(t.player,copy);MeleeRuntime.Reset();Assert(!MasterKeyRuntime.TryUnlock(t.player,new(){DoorState=EFT.Interactive.EDoorState.Locked}),"copy or holster rearmed charge");var actor=new Player{ProfileId=t.player.ProfileId};actor.HandsController=new Player.KnifeController(actor,copy);Assert(!MasterKeyRuntime.TryUnlock(actor,new(){DoorState=EFT.Interactive.EDoorState.Locked}),"actor recreation rearmed charge");});
