Test("Door probe requires an active melee strike, native unobstructed targeting and actual melee range",()=>{var t=Setup("emergency_access");var d=new EFT.Interactive.Door{DoorState=EFT.Interactive.EDoorState.Locked};GameWorld.InteractionTarget=new(){Parent=d};GameWorld.InteractionDistance=.8f;var collider=new KnifeCollider{MaxDistance=1};MasterKeyRuntime.Probe(collider,t.player);Assert(GameWorld.InteractionQueries==0&&d.DoorState==EFT.Interactive.EDoorState.Locked,"idle look opened door");collider.OnHit=_=>{};GameWorld.InteractionDistance=2;MasterKeyRuntime.Probe(collider,t.player);Assert(d.DoorState==EFT.Interactive.EDoorState.Locked,"distant door opened");GameWorld.InteractionDistance=.8f;GameWorld.InteractionTarget=null;MasterKeyRuntime.Probe(collider,t.player);Assert(d.DoorState==EFT.Interactive.EDoorState.Locked,"occluded target opened");GameWorld.InteractionTarget=new(){Parent=d};MasterKeyRuntime.Probe(collider,t.player);Assert(d.DoorState==EFT.Interactive.EDoorState.Open,"strike probe did not open door");});
Test("Linked door colliders resolve, while ordinary and holstered axes cannot use master-key logic",()=>{var t=Setup("emergency_access");var d=new EFT.Interactive.Door{DoorState=EFT.Interactive.EDoorState.Locked};var hit=new Component{Parent=new InteractiveProxy{Link=d}};Assert(MasterKeyRuntime.DoorFrom(hit)==d,"proxy link not resolved");t.player.HandsController=null;Assert(!MasterKeyRuntime.TryUnlock(t.player,d),"holstered bonus");t.player.HandsController=new Player.KnifeController(t.player,new Item{Id="vanilla",StringTemplateId=t.roll.Definition.SourceTemplateId});Assert(!MasterKeyRuntime.TryUnlock(t.player,d)&&d.DoorState==EFT.Interactive.EDoorState.Locked,"ordinary axe unlocked door");});
Test("Native interaction failures are contained and reentrant callbacks cannot unlock a second door",()=>{var t=Setup("emergency_access");Assert(!MasterKeyRuntime.TryUnlock(t.player,new(){DoorState=EFT.Interactive.EDoorState.Locked,ThrowBefore=true}),"failed unlock counted as success");var other=new EFT.Interactive.Door{DoorState=EFT.Interactive.EDoorState.Locked};var d=new EFT.Interactive.Door{DoorState=EFT.Interactive.EDoorState.Locked,Callback=()=>Assert(!MasterKeyRuntime.TryUnlock(t.player,other),"reentrant second use")};Assert(MasterKeyRuntime.TryUnlock(t.player,d)&&other.DoorState==EFT.Interactive.EDoorState.Locked,"failure spent charge or callback opened second door");});

var report=new{passed,failed,checks=passed+failed,results};if(args.Length>0)File.WriteAllText(args[0],JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));
Console.WriteLine($"RESULT {passed}/{passed+failed}");return failed==0?0:1;
